var n=`0100-babk-potato-bake`;var o=`world-0100`;var i=`BY`;var a=`eastern-europe`;var s=4;var l=84;var r={en:`Babkа Potato Bake`,ua:`Картопляна бабка`};var g={en:`A classic dish from Belarus, featuring potato, yellow onion, chicken egg, bacon. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Білорусь. Основні складники: картопля, жовта цибуля, куряче яйце, бекон. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:10,i:[[`potato`,1100,`g`],[`yellow-onion`,140,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`chicken-egg`,2,`pcs`],[`all-purpose-flour`,70,`g`],[`bacon`,200,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Bake in a preheated 180°C oven for about 65 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 65 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:65,i:[[`sunflower-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,120,`g`]]}];var c={slug:n,id:o,country:`BY`,region:a,servings:4,minutes:84,title:r,text:g,steps:u};export{i as country,c as default,o as id,l as minutes,a as region,s as servings,n as slug,u as steps,g as text,r as title};